import fs from "node:fs";
import path from "node:path";

// data/shipping-log.json is generated by scripts/pull-shipping-log.ts from
// sources a visitor can check; the `source` string is printed on the page.

export type ShippingProduct =
  | "HighSchoolTrends.org"
  | "Vitality Weeks"
  | "Squeeze: The Estimation Duel"
  | "Yonmoku: 3D Four in a Row"
  | "FirstHand API"
  | "Writing";

export interface ShippingEntry {
  /** ISO date, YYYY-MM-DD. */
  date: string;
  product: ShippingProduct;
  title: string;
  body?: string;
  version?: string;
  /** e.g. a pull-request number. */
  ref?: string;
  url?: string;
  source: string;
}

const LOG_PATH = path.join(process.cwd(), "data", "shipping-log.json");

let cache: ShippingEntry[] | null = null;

export function getShippingLog(): ShippingEntry[] {
  if (cache) return cache;
  if (!fs.existsSync(LOG_PATH)) {
    cache = [];
    return cache;
  }
  const parsed = JSON.parse(fs.readFileSync(LOG_PATH, "utf8")) as ShippingEntry[];
  cache = [...parsed].sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
  return cache;
}

export function getLatestShipping(n: number): ShippingEntry[] {
  return getShippingLog().slice(0, n);
}

export function groupByMonth(entries: ShippingEntry[]): { month: string; label: string; entries: ShippingEntry[] }[] {
  const buckets = new Map<string, ShippingEntry[]>();
  for (const e of entries) {
    const key = e.date.slice(0, 7);
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key)!.push(e);
  }
  return Array.from(buckets.entries()).map(([month, list]) => ({
    month,
    label: new Date(`${month}-01T00:00:00Z`).toLocaleDateString("en-US", { month: "long", year: "numeric", timeZone: "UTC" }),
    entries: list,
  }));
}
